    private void scanNetwork(){Ui.prompt(this,"扫描自有局域网（IPv4 /24前3段，请核对）",LocalNetworkPrefix.suggest(),prefix->{if(!prefix.matches("(?:\\d{1,3}\\.){2}\\d{1,3}")){Ui.message(this,"网段无效",prefix);return;}for(String octet:prefix.split("\\.")){if(Integer.parseInt(octet)>255){Ui.message(this,"网段无效","IPv4每段必须为0–255");return;}}Ui.confirm(this,"扫描局域网", "仅扫描你拥有或获准访问的网络："+prefix+".1–254，端口5555。",()->work("扫描 "+prefix+".0/24",()->{List<String> found=Collections.synchronizedList(new ArrayList<>());ExecutorService pool=Executors.newFixedThreadPool(16);try{List<Future<?>> fs=new ArrayList<>();for(int i=1;i<255;i++){final String ip=prefix+"."+i;fs.add(pool.submit(()->{try(java.net.Socket sock=new java.net.Socket()){sock.connect(new java.net.InetSocketAddress(ip,5555),350);found.add(ip+":5555");}catch(IOException ignored){}}));}for(Future<?> f:fs)f.get();return found;}finally{pool.shutdownNow();}},found->{if(found.isEmpty())Ui.message(this,"扫描结果","没有发现开放的5555端口。Android11+无线调试通常使用随机端口。");else new AlertDialog.Builder(this).setTitle("发现的地址（连接后验证身份）").setItems(found.toArray(new String[0]),(d,w)->connectTcp(found.get(w))).show();}));});}
