    private String setPhysicalScreenPower(AdbSession target,boolean on,OperationScope scope)throws Exception{
        ScreenServerWorkspace workspace=new ScreenServerWorkspace(this,target);
        StringBuilder report=new StringBuilder();Exception failure=null;boolean commandStarted=false,commandReturned=false;
        try{
            scope.checkActive();
            workspace.deploy((done,total)->!scope.isCancelled());
            scope.checkActive();
            commandStarted=true;
            ShellClient.Result result=new ShellClient(target).run("CLASSPATH="+DeviceCommands.quote(workspace.serverJar())+" app_process / io.github.devicebridge.server.DisplayPowerCommand "+(on?"on":"off"),30000);
            commandReturned=true;
            String outcome=result.success()&&result.text().contains("POWER_REQUEST_SUBMITTED")?"系统已接收物理屏幕请求，请核对实际显示状态。":"请求未确认成功，设备可能不支持该接口。";
            report.append(outcome).append("\n").append(result.text()).append(result.error());scope.record(outcome);
        }catch(Exception e){failure=e;}
        finally{
            for(String warning:workspace.cleanup(!commandStarted||commandReturned)){
                report.append("\n").append(warning);scope.record(warning);
                // Keep the warning available if cancellation/navigation hides this dialog.
                BridgeRuntime.get().report("目标："+target.target()+"\n物理屏幕临时文件清理提醒："+warning);
            }
        }
        if(failure!=null)throw new IOException(String.valueOf(failure.getMessage())+(report.length()==0?"":"\n"+report),failure);
        return report.toString();
    }
