    private void fileMenu(){if(fileDataSession!=BridgeRuntime.session()||fileDataGeneration!=generation){Ui.message(this,"目录尚未加载","请刷新当前设备目录后操作。");return;}final AdbSession bound=BridgeRuntime.session();final int gen=generation;String[] items={"上传文件","新建文件夹","新建空文件",hidden?"隐藏点文件":"显示隐藏文件","排序","全选","反选","取消选择","下载所选","复制所选","剪切所选","粘贴","重命名","详情","删除所选","返回sdcard"};new AlertDialog.Builder(this).setItems(items,(d,w)->guard(()->{if(!sameView(bound,gen))return;switch(w){case 0:pickUpload();break;case 1:case 2:createEntry(w==1);break;case 3:hidden=!hidden;prefs.edit().putBoolean("show_hidden",hidden).apply();showDevice(3);break;case 4:new AlertDialog.Builder(this).setItems(new String[]{"名称","类型","时间","大小"},(x,n)->{sortMode=n;showDevice(3);}).show();break;case 5:for(SyncClient.Entry e:fileEntries)selected.add(e.path);refreshFileSelection();break;case 6:for(SyncClient.Entry e:fileEntries)toggleSelection(e);refreshFileSelection();break;case 7:selected.clear();refreshFileSelection();break;case 8:downloadChoice();break;case 9:case 10:clipboard=new ArrayList<>(selected);clipboardSession=BridgeRuntime.session();clipboardBinding=new SessionBinding<>(clipboardSession,clipboard);cut=w==10;Toast.makeText(this,"已记录 "+clipboard.size()+" 项",0).show();break;case 11:paste();break;case 12:if(selectedFiles().size()!=1)throw new IllegalArgumentException("重命名只能选择一个项目");rename(selectedFiles().get(0));break;case 13:if(selectedFiles().size()!=1)throw new IllegalArgumentException("详情只能选择一个项目");fileDetails(selectedFiles().get(0));break;case 14:deleteSelected();break;case 15:path="/sdcard";showDevice(3);break;}})).show();}
    private void fileDetails(SyncClient.Entry entry){AdbSession target=BridgeRuntime.session();final int detailGeneration=generation;work("读取文件属性",()->{ShellClient.Result result=new ShellClient(target).run(DeviceCommands.stat(entry.path),15000);if(result.success())try{return DeviceParsers.stat(result.text());}catch(IllegalArgumentException unsupported){}return MetadataQuery.stat(this,target,entry.path);},value->{String type=value.isDirectory()?"文件夹":value.isSymbolicLink()?"符号链接":value.isRegularFile()?"普通文件":"特殊文件";String detail="路径："+entry.path+"\n类型："+type+"\n大小："+human(value.sizeBytes)+" ("+value.sizeBytes+"字节)\n修改时间："+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).format(new Date(value.modifiedEpochSeconds*1000))+"\n权限："+Long.toOctalString(value.mode&07777)+"\n所有者UID："+value.uid+"\n所属组GID："+value.gid;TextView text=Ui.text(this,detail,15);text.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.addView(text);new AlertDialog.Builder(this).setTitle(entry.name).setView(scroll).setPositiveButton("确定",null).setNeutralButton("原始属性",(d,w)->{if(sameView(target,detailGeneration))readCommand(entry.name,DeviceCommands.stat(entry.path));}).show();});}
    private void rename(SyncClient.Entry e){final AdbSession bound=BridgeRuntime.session();final int gen=generation;Ui.prompt(this,"重命名",e.name,name->guard(()->{if(sameView(bound,gen)){String destination=DeviceCommands.childPath(parent(e.path),name);requireMoveCapability(bound,gen,()->moveEntries("重命名",bound,gen,Collections.singletonList(e.path),Collections.singletonList(destination),false));}}));}
    private void paste(){
        if(clipboardBinding==null||clipboardSession!=BridgeRuntime.session()){Ui.message(this,"无法粘贴","剪贴板来自另一个设备会话。请返回源设备，或重新选择文件；不会操作当前设备的同名路径。");return;}
        if(clipboard.isEmpty()){Ui.message(this,"粘贴","选择剪贴板为空");return;}
        final AdbSession target=clipboardBinding.require(BridgeRuntime.session());final int gen=generation;
        if(!sameView(target,gen))return;
        final List<String> source=new ArrayList<>(clipboardBinding.objects());final String directory=path;
        if(cut){List<String> destinations=new ArrayList<>();for(String src:source)destinations.add(DeviceCommands.childPath(directory,src.substring(src.lastIndexOf('/')+1)));requireMoveCapability(target,gen,()->moveEntries("移动项目",target,gen,source,destinations,true));return;}
        final SessionBinding<AdbSession> binding=new SessionBinding<>(target,source);
        Ui.confirm(this,"复制项目","目标："+target.target()+"\n"+String.join("\n",source)+"\n\n目标目录："+directory+"\n逐项复制普通文件和目录，不覆盖已有同名项目。链接和特殊文件会明确失败；不保留所有权、权限或时间戳。取消或失败保留已创建的内容，结果未知时需先检查目标。",()->{
            if(!sameView(target,gen))return;
            workScoped("复制项目",scope->{
                binding.require(BridgeRuntime.session());FileCopyManager manager=new FileCopyManager(this,target);boolean all=true;
                try{
                    for(int index=0;index<source.size();index++){
                        if(scope.isCancelled()||Thread.currentThread().isInterrupted()){all=false;for(int j=index;j<source.size();j++)scope.record("未执行（未向设备发出）："+source.get(j));break;}
                        String src=source.get(index),dest=DeviceCommands.childPath(directory,src.substring(src.lastIndexOf('/')+1));
                        try{FileCopyManager.Report report=manager.copy(src,dest);all&=report.complete;for(FileCopyManager.Item item:report.items)scope.record(item.summary());if(!report.warning.isEmpty())scope.record("复制提醒："+report.warning);}
                        catch(Exception failure){all=false;scope.record("未开始复制："+src+"\n"+failure.getMessage());}
                    }
                }finally{manager.close();for(String warning:manager.cleanupWarnings())scope.record("清理提醒："+warning);}
                return new CopyUiResult(all,scope.progressSummary());
            },result->{if(result.complete){clipboard.clear();clipboardBinding=null;}showDevice(3);Ui.message(this,result.complete?"复制已完成":"复制逐项结果",result.summary);});
        });
    }
    private static final class CopyUiResult {final boolean complete;final String summary;CopyUiResult(boolean complete,String summary){this.complete=complete;this.summary=summary;}}
    private void moveEntries(String action,AdbSession target,int gen,List<String> sources,List<String> destinations,boolean clearClipboard){
        final SessionBinding<AdbSession> binding=new SessionBinding<>(target,sources);final List<String> outputs=Collections.unmodifiableList(new ArrayList<>(destinations));
        StringBuilder review=new StringBuilder("目标：").append(target.target());for(int i=0;i<sources.size();i++)review.append("\n\n").append(sources.get(i)).append("\n→ ").append(outputs.get(i));
        review.append("\n\n不覆盖同名目标。完成后核验源消失及精确目标身份；普通文件同时核验SHA256。跨文件系统、取消或无法核验时显示结果未知，需检查两处路径。");
        Ui.confirm(this,action,review.toString(),()->{if(!sameView(target,gen))return;workScoped(action,scope->{
            binding.require(BridgeRuntime.session());FileCopyManager manager=new FileCopyManager(this,target);boolean all=true;
            try{for(int i=0;i<binding.objects().size();i++){
                if(scope.isCancelled()||Thread.currentThread().isInterrupted()){all=false;for(int j=i;j<binding.objects().size();j++)scope.record("未执行（未向设备发出）："+binding.objects().get(j));break;}
                String source=binding.objects().get(i),destination=outputs.get(i);
                try{FileCopyManager.MoveReport report=manager.move(source,destination);all&=report.verified();scope.record(report.summary(source,destination));}
                catch(Exception failure){all=false;scope.record("未开始移动："+source+"\n"+failure.getMessage());}
            }}finally{manager.close();for(String warning:manager.cleanupWarnings())scope.record("清理提醒："+warning);}
            return new CopyUiResult(all,scope.progressSummary());
        },result->{if(result.complete&&clearClipboard){clipboard.clear();clipboardBinding=null;}showDevice(3);Ui.message(this,result.complete?action+"已核验":action+"逐项结果",result.summary);});});
    }
    private void requireMoveCapability(AdbSession target,int gen,Runnable next){work("检查移动兼容性",()->{ShellClient.Result result=new ShellClient(target).run(DeviceCommands.property("ro.build.version.sdk"),10000);if(!result.success())throw new IOException("未能读取目标系统版本，未执行移动");try{return Integer.parseInt(result.text().trim());}catch(NumberFormatException invalid){throw new IOException("目标系统版本未知，未执行移动",invalid);}},sdk->{if(!sameView(target,gen))return;if(sdk<23){Ui.message(this,"此设备暂不支持安全移动","旧系统的mv没有可用的无覆盖能力。移动和重命名尚未完成兼容，未执行命令；可先使用已校验复制。不会退回可能覆盖目标的mv。");return;}next.run();});}
    private void deleteSelected(){List<String> paths=new ArrayList<>(selected);if(paths.isEmpty()){Ui.message(this,"删除","请先选择项目");return;}List<String> commands=new ArrayList<>();for(String p:paths)commands.add(DeviceCommands.delete(p,true));batch("永久删除",paths,commands,"这些文件及文件夹内容可能无法恢复。",()->showDevice(3));}
    private void downloadChoice(){pendingDownloads=selectedFiles();if(pendingDownloads.isEmpty()){Ui.message(this,"下载","请先选择文件");return;}pendingTarget=BridgeRuntime.session();openLocalPicker(PICK_DOWNLOAD,LocalFilesActivity.MODE_DIRECTORY);}
    private void openRemote(SyncClient.Entry e){AdbSession s=BridgeRuntime.session();work("下载后打开 "+e.name,()->{File dir=new File(getCacheDir(),"exports");dir.mkdirs();File out=new File(dir,"open-"+System.currentTimeMillis()+"-"+safeName(e.name));boolean verified=false;try(FileOutputStream dest=new FileOutputStream(out)){new FileTransferManager(this,s).download(e.path,dest,(done,total)->!Thread.currentThread().isInterrupted());verified=true;}finally{if(!verified)out.delete();}return out;},out->{Uri uri=new Uri.Builder().scheme("content").authority("io.github.devicebridge.goldenbeetle.files").appendPath(out.getName()).build();Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,getContentResolver().getType(uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(i);}catch(ActivityNotFoundException ex){Ui.message(this,"无法打开","本机没有可查看此文件的应用。可改用下载保存。");}});}
    private static String parent(String path){int at=path.lastIndexOf('/');return at<=0?"/":path.substring(0,at);}
    private static String extension(String name){int at=name.lastIndexOf('.');return at<0?"":name.substring(at).toLowerCase(Locale.ROOT);}
    private static String safeName(String s){return s.replace('/','_').replace('\\','_').replace('\0','_');}
    private static String human(long size){if(size<1024)return size+" B";if(size<1048576)return String.format(Locale.ROOT,"%.1f KB",size/1024d);if(size<1073741824)return String.format(Locale.ROOT,"%.1f MB",size/1048576d);return String.format(Locale.ROOT,"%.1f GB",size/1073741824d);}
    private List<JSONObject> packages=new ArrayList<>();private boolean appSystem=true,appUser=true,appEnabled=true,appDisabled=true,quickPackages;private String appSearch="";private int appSort;
    private void apps(LinearLayout body){body.addView(Ui.text(this,"正在读取应用…",14));appList(body,Collections.emptyList());AdbSession target=viewSession;initialModuleRead("读取应用列表",()->loadPackages(target),all->{appDataSession=target;appDataGeneration=generation;packages=all;renderApps(body);});}
    private List<JSONObject> loadPackages(AdbSession target)throws Exception{List<JSONObject> result=new ArrayList<>();ShellClient shell=new ShellClient(target);String fallbackReason="";if(!quickPackages){String workspace="/data/local/tmp/goldenbeetle-metadata-"+UUID.randomUUID();String remote=workspace+"/metadata-server.jar";boolean reserved=false;try{ShellClient.Result reserve=shell.run("umask 077; mkdir "+DeviceCommands.quote(workspace),10000);if(!reserve.success())throw new IOException("无法预留元数据工作目录："+reserve.text()+reserve.error());reserved=true;try(InputStream asset=getAssets().open("metadata-server.jar");SyncClient sync=new SyncClient(target,30000)){byte[] bytes=readAll(asset,4*1024*1024);sync.push(remote,new ByteArrayInputStream(bytes),bytes.length,0600,System.currentTimeMillis()/1000,(done,total)->!Thread.currentThread().isInterrupted());}ShellClient.Result permissions=shell.run("chmod 0400 "+DeviceCommands.quote(remote),10000);if(!permissions.success())throw new IOException("无法保护元数据组件");ShellClient.Result output=shell.run("CLASSPATH="+DeviceCommands.quote(remote)+" app_process / io.github.devicebridge.server.MetadataServer icons",60000);for(String line:output.text().split("\\r?\\n"))if(line.startsWith("{"))result.add(new JSONObject(line));if(!result.isEmpty())return result;fallbackReason=output.error().isEmpty()?"设备元数据服务未返回可读条目":output.error();}catch(Exception e){if(Thread.currentThread().isInterrupted())throw e;fallbackReason=String.valueOf(e.getMessage());}finally{if(reserved)for(String warning:FileTransferManager.cleanupWorkspace(target,workspace))BridgeRuntime.get().report("目标："+target.target()+"\n元数据临时文件清理提醒："+warning);}}

        Set<String> systems=readPackageSet(shell,DeviceCommands.PackageFilter.SYSTEM),disabled=readPackageSet(shell,DeviceCommands.PackageFilter.DISABLED);for(String name:readPackageSet(shell,DeviceCommands.PackageFilter.ALL)){JSONObject j=new JSONObject();j.put("packageName",name);j.put("label",name);j.put("system",systems.contains(name));j.put("enabled",!disabled.contains(name));j.put("metadataUnavailable",true);j.put("metadataWarning",quickPackages?"已选择只加载包名":fallbackReason);result.add(j);}return result;}
    private Set<String> readPackageSet(ShellClient shell,DeviceCommands.PackageFilter filter)throws IOException{ShellClient.Result result=shell.run(DeviceCommands.listPackages(filter,0),30000);Set<String> found=packageSet(result.text());if(!result.success()||found.isEmpty()){result=shell.run(DeviceCommands.listPackagesLegacy(filter,0),30000);found=packageSet(result.text());}if(!new DeviceOperations.Result(result.text(),result.error(),result.exitCode).isSuccess()||(!result.text().trim().isEmpty()&&found.isEmpty()))throw new IOException("应用列表读取未完成："+result.text()+result.error());return found;}
