    private void showPackageDetails(JSONObject app){String pkg=app.optString("packageName");StringBuilder details=new StringBuilder();String[][] fields={{"应用名称","label"},{"包名","packageName"},{"版本名称","versionName"},{"版本号","versionCode"},{"最低API","minSdk"},{"目标API","targetSdk"},{"安装位置","sourceDir"},{"启动Activity","launchComponent"}};for(String[] field:fields)details.append(field[0]).append("：").append(app.has(field[1])?app.optString(field[1]):"未提供").append('\n');details.append("状态：").append(app.optBoolean("enabled",true)?"启用":"停用").append("\n类型：").append(app.optBoolean("system")?"系统应用":"用户应用");if(app.has("size"))details.append("\n基础APK大小：").append(human(app.optLong("size")));for(String[] field:new String[][]{{"首次安装","firstInstallTime"},{"最近更新","lastUpdateTime"}})if(app.optLong(field[1])>0)details.append("\n").append(field[0]).append("：").append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).format(new Date(app.optLong(field[1]))));TextView text=Ui.text(this,details.toString(),15);text.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.addView(text);new AlertDialog.Builder(this).setTitle("应用详情").setView(scroll).setPositiveButton("确定",null).setNeutralButton("完整系统信息",(d,w)->readCommand("应用详情\n"+pkg,DeviceCommands.packageDetails(pkg))).show();}
