    private void localAppHelp(AdbSession target,int gen){
        if(!sameView(target,gen))return;
        String status="";
        if(Build.VERSION.SDK_INT>=30){
            try{status="\n系统报告应用列表权限："+(getPackageManager().checkPermission("android.permission.QUERY_ALL_PACKAGES",getPackageName())==PackageManager.PERMISSION_GRANTED?"已授予":"未授予")+"。";}
            catch(RuntimeException unavailable){status="\n当前无法读取系统权限状态。";}
        }
        String explanation="本机应用列表只在本机读取，不会上传。\n\nAndroid 11 及以上的应用可见性权限已在安装包中声明，它是安装时权限，不会弹出常规的运行时授权窗口。"+status
                +"\n\n部分系统可能另外限制应用列表。可打开系统应用信息；若存在“读取应用列表”等开关，请允许后返回重试。各品牌设置不同，尚未逐一验证。工作资料或其他用户中的应用也可能不可见。"
                +"\n\n此功能不需要相册或所有文件访问权限。仅当你选择一个应用并确认安装目标后，才会传输该应用的固定 APK 快照。";
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("本机应用权限说明").setMessage(explanation)
                .setPositiveButton("打开应用设置",(d,w)->{
                    try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}
                    catch(ActivityNotFoundException|SecurityException unavailable){Ui.message(this,"无法打开应用信息","请手动前往系统设置 → 应用 → 本应用，检查权限设置后返回重试。");}
                }).setNeutralButton("重试",(d,w)->{if(sameView(target,gen))localAppPicker();})
                .setNegativeButton("关闭",null).show();ownDialog(dialog);
    }
    private void installLocalApp(AdbSession target,String packageName,int gen){
        if(!sameView(target,gen))return;
        workScoped("正在固定本机应用 APK…",scope->{
            LocalAppSelection selected=LocalApps.read(getPackageManager(),packageName);
            List<Uri> uris=new ArrayList<>();Map<String,String> tokens=new LinkedHashMap<>();
            for(String path:selected.apkPaths){
                scope.checkActive();Uri uri=Uri.fromFile(new File(path));uris.add(uri);
                try{tokens.put(uri.toString(),Compatibility.sourceToken(new File(path)));}
                catch(IOException unavailable){throw new IOException("无法读取所选本机应用的 APK。系统可能限制读取，或应用正在更新。请重试或检查本机应用权限说明。原因："+unavailable.getMessage(),unavailable);}
            }
            selected.requireUnchanged(LocalApps.read(getPackageManager(),packageName));
            return prepareInstall(target,uris,tokens,gen,selected,scope);
        },this::reviewInstall);
    }
    private PackageCommandStrategy packageStrategy(AdbSession target)throws Exception {
        ShellClient.Result sdk=new ShellClient(target).run(DeviceCommands.property("ro.build.version.sdk"),15000);
        if(!sdk.success())throw new IOException("无法读取目标 Android API："+sdk.text()+sdk.error());
        return PackageCommandStrategy.fromSdkOutput(sdk.text());
    }
    private void confirmPackageCommand(String action,AdbSession target,int gen,PackageCommandStrategy.CommandPlan plan,String consequence){
        if(!sameView(target,gen))return;
        Ui.confirm(this,action,"目标："+target.target()+"\n"+plan.scopeDescription()+"\n"+consequence+"\n\n命令："+plan.command,()->{
            if(!sameView(target,gen))return;
            work(action,()->new ShellClient(target).run(plan.command,60000),r->Ui.message(this,r.success()?"命令执行完成":"执行结果需检查",r.text()+"\n"+r.error()+"\n退出码："+r.exitCode+"\n需读取目标状态验证实际效果。"));
        });
    }
    private void uninstallPackage(AdbSession target,int gen,String pkg,boolean keepData,boolean system){
        if(!sameView(target,gen))return;
        work("检查卸载兼容性",()->packageStrategy(target).uninstall(pkg,0,keepData),plan->{
            String consequence=pkg+"\n"+(keepData?"尝试保留上述范围内的数据，不保证系统支持或之后可恢复。":"会删除上述范围内的应用及其数据。");
            if(system)consequence+="\n系统应用操作可能影响设备功能；旧版全用户卸载可能移除更新并回退系统版本。";
            confirmPackageCommand("卸载应用",target,gen,plan,consequence);
        });
    }
