            ShellClient.Result all=sh.run(DeviceCommands.listSystemPackagesIncludingUninstalled(0),30000),installed=sh.run(DeviceCommands.listPackagesLegacy(DeviceCommands.PackageFilter.SYSTEM,0),30000);
