    private void browseHistory(int step){if(commandHistory.isEmpty())return;historyIndex=Math.max(0,Math.min(commandHistory.size(),historyIndex+step));command.setText(historyIndex==commandHistory.size()?"":commandHistory.get(historyIndex));command.setSelection(command.length());}
    private void runTerminal(){String cmd=command.getText().toString().trim();if(cmd.startsWith("adb shell "))cmd=cmd.substring(10).trim();if(cmd.isEmpty()){command.setError("请输入命令");return;}if(!"clear".equalsIgnoreCase(cmd)&&terminalExitRequested&&(interactiveShell==null||!interactiveShell.isClosed())){command.setError("终端正在退出，请等待结束后再运行命令");return;}commandHistory.add(cmd);historyIndex=commandHistory.size();command.setText("");command.setError(null);if("clear".equalsIgnoreCase(cmd)){clearTerminal();return;}terminalExitRequested="exit".equals(cmd);sendTerminal(cmd);}
    private void clearTerminal(){TerminalRenderer.Output output=terminalOutput;if(output!=null)output.flush();terminalRenderer.clearKeepingLastLine();}
    private void sendTerminal(String cmd){final AdbSession target=BridgeRuntime.session();final int gen=generation;final int epoch=terminalEpoch;final TerminalRenderer renderer=terminalRenderer;TerminalRenderer.Output previous=terminalOutput;if(previous!=null)previous.flush();
        terminalTask=terminalExecutor.submit(()->{TerminalRenderer.Output output=null;try{InteractiveShell shell; synchronized(terminalLock){if(terminalEpoch!=epoch||generation!=gen||isDestroyed()||BridgeRuntime.session()!=target)return;shell=interactiveShell;output=terminalOutput;}
            if(shell==null||shell.isClosed()||terminalTarget!=target){final Object token=new Object();TerminalRenderer.Output freshOutput=new TerminalRenderer.Output(BridgeRuntime.UI,()->!isDestroyed()&&generation==gen&&terminalEpoch==epoch&&BridgeRuntime.session()==target&&terminalRenderToken==token,renderer);output=freshOutput;
                synchronized(terminalLock){if(terminalEpoch!=epoch||generation!=gen||isDestroyed()||BridgeRuntime.session()!=target)return;terminalRenderToken=token;terminalOutput=freshOutput;}
                if(shell!=null&&!shell.isClosed())shell.close();InteractiveShell fresh=new InteractiveShell(target,freshOutput);
                boolean stale;synchronized(terminalLock){stale=terminalEpoch!=epoch||generation!=gen||isDestroyed()||BridgeRuntime.session()!=target;if(!stale){interactiveShell=fresh;terminalTarget=target;shell=fresh;}}if(stale){fresh.close();return;}
            }
            if(cmd!=null){synchronized(terminalLock){if(terminalEpoch!=epoch||generation!=gen||BridgeRuntime.session()!=target)return;}shell.line(cmd);}
        }catch(Exception e){if(output!=null)output.error(e);final TerminalRenderer.Output failedOutput=output;BridgeRuntime.UI.post(()->{if(!isDestroyed()&&generation==gen&&terminalEpoch==epoch&&BridgeRuntime.session()==target&&terminalOutput==failedOutput)terminalExitRequested=false;});}});tasks.add(terminalTask);
    }
    private void stopTerminal(){InteractiveShell shell=interactiveShell;final int epoch=terminalEpoch;final AdbSession target=terminalTarget;if(shell!=null)BridgeRuntime.IO.submit(()->{if(terminalEpoch!=epoch||interactiveShell!=shell||BridgeRuntime.session()!=target)return;try{shell.interrupt();}catch(IOException error){TerminalRenderer.Output output=terminalOutput;if(output!=null&&terminalEpoch==epoch)output.error(error);}});}
