    private void screenshot(){AdbSession target=BridgeRuntime.session();workScoped("屏幕截图",scope->{ScreenshotCapture capture=scope.own(new ScreenshotCapture(target));try{ScreenshotCapture.Result result=capture.capture(30000,32*1024*1024);return result;}finally{capture.close();if(!capture.cleanupWarning().isEmpty())scope.record("截图临时文件清理提醒："+capture.cleanupWarning());}},result->{byte[] bytes=result.png;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null){Ui.message(this,"截图失败","设备返回的图像无法解码。"+result.cleanupWarning);return;}ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(bitmap);AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle("屏幕截图").setView(image);if(!result.cleanupWarning.isEmpty())dialog.setMessage("临时文件清理提醒："+result.cleanupWarning);dialog.setPositiveButton("保存",(d,w)->{if(ScreenshotStore.hasDirectory(this)){work("保存截图",()->ScreenshotStore.saveConfigured(this,bytes),uri->Ui.message(this,"截图已保存","已保存到设置中的截图目录。"));return;}cachedScreenshot=bytes;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("image/png").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"金甲虫ADB助手-"+System.currentTimeMillis()+".png"),13);}).setNegativeButton("关闭",null).show();});}
